interface User {
  id: number;
  username: string;
  isActive: boolean;
}

const primaryUser: User = {
  id: 101,
  username: "alex_dev",
  isActive: true
};

console.log(`User: ${primaryUser.username}, Active: ${primaryUser.isActive}`);

interface Product {
  title: string;
  price: number;
  description?: string;
  discountPercentage?: number;
}

// Instance with only required fields
const item1: Product = {
  title: "Wireless Mouse",
  price: 29.99
};

// Instance with optional fields supplied
const item2: Product = {
  title: "Mechanical Keyboard",
  price: 89.99,
  description: "RGB Backlit Red Switches",
  discountPercentage: 15
};

interface Config {
  readonly apiKey: string;
  readonly maxRetries: number;
  environment: string;
}

const serverConfig: Config = {
  apiKey: "secret_abc_123",
  maxRetries: 3,
  environment: "production"
};

// Reassigning regular property is allowed
serverConfig.environment = "staging";

// INVALID: TypeScript produces a compile-time error:
// serverConfig.apiKey = "new_key";
// Error: Cannot assign to 'apiKey' because it is a read-only property.

interface Vehicle {
  make: string;
  model: string;
  year: number;
}

// ElectricCar inherits all properties from Vehicle and adds batteryCapacity
interface ElectricCar extends Vehicle {
  batteryCapacityKwh: number;
  autopilotEnabled: boolean;
}

const mySedan: ElectricCar = {
  make: "Tesla",
  model: "Model 3",
  year: 2024,
  batteryCapacityKwh: 75,
  autopilotEnabled: true
};

console.log(`${mySedan.year} ${mySedan.make} ${mySedan.model}`);

### Key Differences Between `type` and `interface`:

1. **Declaration Merging:**
   * **`interface`:** Merges automatically when defined multiple times under the same name (essential for extending library types).
   * **`type`:** Cannot be merged; defining the same type alias twice results in a duplicate identifier compile error.

2. **Unions and Primitives:**
   * **`type`:** Can represent primitive types, unions (`type Status = 'open' | 'closed'`), intersections, and tuples directly.
   * **`interface`:** Can only describe object and class shapes.

### Code Demonstration of Merging:
```typescript
interface WindowSettings {
  width: number;
}
interface WindowSettings {
  height: number; // Automatically merged into { width: number; height: number; }
}
```

### Best Practice Recommendation:
Use **`interface`** for public APIs and object models to allow consumer extension, and **`type`** for complex unions, mapped types, or utility transformations.

interface InventoryCounts {
  // Index signature: any string key maps to a number value
  [itemName: string]: number;

  // Known required property adhering to the signature type
  totalItems: number;
}

const warehouse: InventoryCounts = {
  totalItems: 450,
  laptops: 120,
  monitors: 85,
  cables: 245
};

console.log(`Laptops in stock: ${warehouse["laptops"]}`);
